/**
 * A minimal POSIX ustar writer for export bundles (regular files only). Paths
 * are generated by us, ASCII, and at most 100 bytes.
 */
import { gzipSync } from "node:zlib";

const BLOCK = 512;

function header(path: string, size: number, mtime: Date): Buffer {
  const h = Buffer.alloc(BLOCK);
  if (Buffer.byteLength(path) > 100 || !/^[\x20-\x7e]+$/.test(path)) throw new Error(`tar: bad path ${path}`);
  const oct = (n: number, len: number) => `${n.toString(8).padStart(len - 1, "0")}\0`;
  h.write(path, 0, "ascii");
  h.write(oct(0o600, 8), 100, "ascii"); // mode
  h.write(oct(0, 8), 108, "ascii"); // uid
  h.write(oct(0, 8), 116, "ascii"); // gid
  h.write(oct(size, 12), 124, "ascii");
  h.write(oct(Math.floor(mtime.getTime() / 1000), 12), 136, "ascii");
  h.write("        ", 148, "ascii"); // checksum placeholder (spaces)
  h.write("0", 156, "ascii"); // regular file
  h.write("ustar\0", 257, "ascii");
  h.write("00", 263, "ascii");
  let sum = 0;
  for (const b of h) sum += b;
  h.write(`${sum.toString(8).padStart(6, "0")}\0 `, 148, "ascii");
  return h;
}

export interface TarEntry {
  path: string;
  data: Uint8Array;
}

/** A gzipped tar of `entries`. */
export function tarGz(entries: TarEntry[], mtime = new Date()): Buffer {
  const parts: Buffer[] = [];
  for (const e of entries) {
    parts.push(header(e.path, e.data.byteLength, mtime), Buffer.from(e.data));
    const pad = (BLOCK - (e.data.byteLength % BLOCK)) % BLOCK;
    if (pad) parts.push(Buffer.alloc(pad));
  }
  parts.push(Buffer.alloc(BLOCK * 2));
  return gzipSync(Buffer.concat(parts));
}

/** Reads a (gunzipped) tar back into entries. For tests and verification. */
export function untar(tar: Buffer): TarEntry[] {
  const out: TarEntry[] = [];
  let off = 0;
  while (off + BLOCK <= tar.length) {
    const h = tar.subarray(off, off + BLOCK);
    if (h.every((b) => b === 0)) break;
    const path = h.subarray(0, 100).toString("ascii").replace(/\0.*$/s, "");
    const size = Number.parseInt(h.subarray(124, 136).toString("ascii").replace(/\0.*$/s, ""), 8);
    off += BLOCK;
    out.push({ path, data: tar.subarray(off, off + size) });
    off += Math.ceil(size / BLOCK) * BLOCK;
  }
  return out;
}
